-- 量子计算四路线国内标的补齐（2026-11-28）
-- 三家中性原子/离子阱企业补全管理层、产品、融资与里程碑；三家新建
-- 合并语义：data || '{...}'::jsonb 为顶层浅合并，只覆盖列出的键，不动其余字段

-- 中科酷原（中性原子（光镊阵列 + 里德堡阻塞）量子计算整机厂商，汉原系列已实现商用交付；同…）
UPDATE public.research_companies
SET data = data || '{"desc": "中性原子（光镊阵列 + 里德堡阻塞）量子计算整机厂商，汉原系列已实现商用交付；同时做原子重力仪等量子精密测量。核心团队源自中科院精密测量科学与技术创新研究院（原武汉物理与数学研究所，1990 年代起开展冷原子研究），为湖北省量子技术产业链链主。", "descDetail": "汉原系列用聚焦激光作光镊，把铷原子逐粒捕获排成阵列，每个原子一个量子比特；计算时把部分原子激发到高能里德堡态，靠范德瓦尔斯力产生强相互作用完成纠缠与门操作。原子本身不带电、对环境噪声不敏感，因而可在近室温部署，不需要稀释制冷机——这是中性原子路线跑得快的主因。汉原 2 号首创「双核」架构：一个核负责计算，另一个核实时纠错或并行运算，用来破解单核架构下比特扩展受限与近邻串扰。", "tech": [{"date": "2026-11", "kind": "交付", "title": "汉原 2 号完成签约交付，采购方武汉金控集团；同步上线易原量子算力平台，量子模拟功能免费开放"}, {"date": "2026-05", "kind": "产品", "title": "发布汉原 2 号：全球首台双核中性原子量子计算机，200 物理比特（100 个 Rb87 + 100 个 Rb85）"}, {"date": "2026-05", "kind": "指标", "title": "相干时间由汉原 1 号的 10ms 提升至 300ms；双比特门保真度由 90% 提升至 99%"}, {"date": "2025", "kind": "指标", "title": "汉原 3 号规划 1,000 量子比特，计划 2027 年发布"}, {"date": "2024", "kind": "产品", "title": "汉原 1 号：国内首台商用中性原子量子计算机，实现批量稳定交付并出口海外"}, {"date": "2024", "kind": "产品", "title": "原子重力仪及重力数据测量服务投入商用"}], "productLine": ["汉原 2 号：200 物理比特，铷双核架构，整机一人高、标准机柜式集成、功耗 <7kW，普通室内环境可部署", "汉原 1 号：国内首台商用中性原子量子计算机，2024 年已批量稳定交付", "易原量子算力平台：三层使用体系（可视化改量子线路 / 智能体自动选算法 / 直接跑真机），量子模拟免费", "原子重力仪：量子精密测量业务线，提供重力数据测量服务"], "executives": [{"bio": "工商登记为董事兼经理（2026-06-29 任职），公司对外代表。主导汉原系列产品发布与商业化，公开表述「汉原 2 号已跻身国际第一梯队」。团队技术源头为中科院精密测量科学与技术创新研究院的冷原子研究积累。", "name": "汤彪", "title": "董事、总经理"}], "customers": "武汉金控集团（汉原 2 号首台采购方，委托武汉量子技术研究院存放运维）、华源证券、汉融通；已揭牌「量子金融合作实验室」。首批场景为金融资产配置、分子模拟、电网调度。", "orders": "2026-06-04 中科酷原、武汉量子技术研究院、湖北金融租赁、华源证券、汉融通五方签约，「汉原系列」在汉首张商业订单落地；汉原 1 号累计交付为批量级，含海外客户（未披露台数与金额）。", "milestones": ["2026-11 汉原 2 号交付武汉金控；易原量子算力平台上线", "2026-08 在广州产投推动下落子广州天河广棠科创城，搭建量子算力公共资源服务平台（大湾区公司总经理赵忠斌）", "2026-05-07 发布汉原 2 号（全球首台双核中性原子量子计算机）", "2026-01 完成近亿元战略融资，中国移动链长基金（中移和创）独家投资", "2024 汉原 1 号发布并实现商业化交付，国内首台商用中性原子量子计算机"], "funding": [{"inv": "中国移动链长基金（中移和创）独家投资", "date": "2026-01", "round": "战略轮", "amount": "近亿元"}], "latestTech": "汉原 2 号：200 物理比特双核架构，相干 300ms、双比特门 99%，<7kW 可近室温部署；汉原 3 号规划 1,000 比特（2027）", "lastFunding": "2026-01", "latestFunding": "2026-01 · 战略轮近亿元（中移和创独家）"}'::jsonb,
    round = '战略轮',
    updated_at = now()
WHERE name = '中科酷原';

-- 启科量子（国开启科量子技术（北京）有限公司，2016-04 成立，亚洲首家把离子阱量子计算…）
UPDATE public.research_companies
SET data = data || '{"desc": "国开启科量子技术（北京）有限公司，2016-04 成立，亚洲首家把离子阱量子计算机推进到工程样机阶段的企业，走分布式离子阱路线，兼做量子通信设备，定位「量子计算 + 量子通信」双赛道全栈。总部合肥高新区，北京海淀设主体。", "descDetail": "天算 1 号（AbaQ-1）采用 Yb-171 镱离子天然量子比特，全同性好、相干时间长；镱属我国特有重稀土，对全产业链自主可控有特殊意义。整机由工作环境控制、离子阱、光学、电子测控四大子系统构成，模块以插箱方式互联，可单独更换。与超导相比离子阱门速慢 2–3 个数量级，因此公司选择分布式架构 + 光子互联扩规模，而非单阱堆比特。", "tech": [{"date": "2026", "kind": "指标", "title": "天算 1 号（AbaQ-1）工程机：80+ 物理比特，相干 >800ms，单比特门 98%、双比特门 >98%，Grover 算法成功率 99%"}, {"date": "2026", "kind": "产品", "title": "QuSoil 量子测控系统开放细粒度硬件控制接口，支持 NVIDIA Ising 校准/解码模型接入"}, {"date": "2026", "kind": "合作", "title": "联合中山大学开展 NVIDIA Ising 模型测试，侧重离子阱噪声模型下的解码器适配"}, {"date": "2025", "kind": "产品", "title": "天算 1 号：国内首台模块化离子阱量子计算工程机，通过量子信息、原子物理、光电子学专家评审"}, {"date": "2022", "kind": "产品", "title": "推出 OneQloud 量子-经典混合算力云平台"}], "productLine": ["天算 1 号（AbaQ-1）：80+ 物理比特离子阱工程机，Yb-171 天然量子比特，相干 >800ms", "QuSoil 量子测控系统：细粒度硬件控制接口，支持第三方 AI 校准/解码模型", "OneQloud 量子云计算平台：量子-经典混合算力，面向高校、科研机构与行业用户", "量子通信设备：2003 年起即推出全球首个商用量子通信设备，为国内量子通信骨干网供应商之一", "定制离子阱系统与核心光学/电子学部件"], "executives": [{"bio": "国开启科量子技术（北京）有限公司法定代表人、执行董事（2019-01-14 任职），亦任安徽主体法定代表人。通过宁波京量信管理合伙企业（有限合伙）控制，集团成员 6 家。", "name": "李杨", "title": "执行董事、实际控制人"}, {"bio": "2019-01-14 起任公司经理，负责日常经营。", "name": "陈柳平", "title": "经理"}, {"bio": "负责离子阱量子计算技术路线与前瞻研究，对外代表公司参与中法量子技术交流等国际对话。", "name": "罗乐", "title": "首席科学家"}, {"bio": "负责运营与产业化推进。", "name": "杨志国", "title": "常务副总裁"}, {"bio": "负责市场与品牌，主导中法量子产业对接等国际交流。", "name": "朱子南", "title": "CMO"}, {"bio": "2023-05-29 起任财务负责人。", "name": "付雪", "title": "财务负责人"}, {"bio": "2020-07-01 起任监事。", "name": "裴丽", "title": "监事"}], "customers": "国家通信网、能源网、交通物流网方向客户；OneQloud 平台面向高校与科研机构；与中山大学等高校开展离子阱噪声模型与解码算法联合研究。", "milestones": ["2026 天算 1 号指标更新至 80+ 比特、相干 >800ms、双比特门 >98%", "2025 发布国内首台模块化离子阱量子计算工程机天算 1 号（AbaQ-1）", "2022-12-06 国开启科量子技术（安徽）有限公司成立，注册资金 3,731 万元，总部落合肥高新区", "2019-01 北京主体完成执行董事、经理登记，李杨任执行董事", "2016-04-14 国开启科量子技术（北京）有限公司成立，注册资本 3,587.5 万元"], "funding": [{"inv": "2 家私募机构（工商口径仅 1 起融资事件）", "date": "—", "round": "天使轮", "amount": "未披露"}], "latestTech": "天算 1 号（AbaQ-1）工程机 80+ 物理比特，相干 >800ms，双比特门保真度 >98%，Grover 成功率 99%", "lastFunding": "—", "latestFunding": "仅披露 1 起天使轮融资事件，金额与投资方未公开"}'::jsonb,
    updated_at = now()
WHERE name = '启科量子';

-- 华翊博奥（品牌名「华翊量子」，清华量子信息中心孵化、段路明院士创立（2022-01），国内…）
UPDATE public.research_companies
SET data = data || '{"descDetail": "离子阱路线用电磁场把带电离子囚禁在超高真空中，用超窄线宽激光操控其内态。核心优势是比特天然全同（同种离子）、相干时间长、任意两离子可直接纠缠（全连接）；瓶颈是门速比超导慢 2–3 个数量级，且离子数上百后一维链振动模式复杂度爆炸。华翊的解法是低温离子阱 + 二维离子阵列：2024 年 Nature 论文实现 512 个离子二维晶体稳定囚禁、用 300 个离子做伊辛模型模拟，为二维扩展提供实验依据。", "executives": [{"bio": "中国科学院院士、清华大学教授。长期从事量子信息、量子通信与量子计算研究，曾在美国密歇根大学任教，2018 年全职回国加入清华大学。DLCZ 量子中继方案的共同提出者之一，近年主攻大规模离子阱量子计算。", "name": "段路明", "title": "创始人、首席科学家", "shares": "直接持股（股东名单在列）"}, {"bio": "中国科学技术大学本科、博士，曾任清华大学副研究员，有海外科研经历。法定代表人，负责公司经营与技术商业化。公司注册资本 868.8856 万元、实缴 762.1804 万元。", "name": "姚麟", "title": "董事长、经理（CEO）", "tenure": "2022-01 至今"}, {"bio": "清华大学本科、博士、博士后，离子阱量子计算科研背景，负责核心技术研发与整机工程化。", "name": "杨蒿翔", "title": "首席技术官（CTO）"}, {"bio": "清华大学本科、博士，长期从事离子阱量子计算研究。", "name": "梅全鑫", "title": "量子计算技术总监、监事"}, {"bio": "负责量子算法与行业应用研究。", "name": "赵文定", "title": "副总经理、算法总监、董事"}, {"bio": "君联资本代表，A 轮投资方。", "name": "李家庆", "title": "董事"}, {"bio": "负责财务与合规。", "name": "杨国兵", "title": "董事、财务负责人"}], "milestones": ["2026-06-05 北京经开区确认 HYQ-B100 已正式交付中国移动研究院", "2026-05 完成 A+ 轮融资（建投投资、中信建投投资、中车资本），老股东百度风投、北京信息产业发展投资基金、君联资本追加；公开双比特门保真度 >99.7%、稳定囚禁离子超 1,000 个", "2025-07 完成数亿元 A 轮（社保基金中关村自主创新专项基金、北京信息产业发展投资基金、君联资本）", "2025 发布第二代百比特低温离子阱整机 HYQ-B100", "2024-05-29 参与的清华大学团队在 Nature 发表 512 离子二维晶体、300 离子伊辛模拟成果", "2023-04-27 发布第一代常温离子阱商业化原型机 HYQ-A37（37 比特）", "2022-01-28 华翊博奥（北京）量子科技有限公司成立，清华大学量子信息中心孵化"], "execChanges": [{"date": "2026-05", "event": "完成 A+ 轮融资，建投投资、中信建投投资、中车资本进入，老股东追加"}, {"date": "2025-07", "event": "完成数亿元 A 轮，社保基金中关村专项基金、北京信息产业发展投资基金、君联资本入局"}, {"date": "2024-01", "event": "中移资本战略投资数千万，随后 HYQ-B100 交付中国移动研究院"}], "latestFunding": "2026-05 · A+ 轮（建投投资领投），累计融资超 5 亿元；A+ 轮金额与投后估值未披露", "customers": "中国移动研究院（HYQ-B100 已交付）、清华大学、中国科学院半导体研究所、中石油（北京）数智研究院（油气产业链优化、油气藏数值模拟、催化剂模拟）。"}'::jsonb,
    round = 'A+ 轮',
    updated_at = now()
WHERE name = '华翊博奥';

INSERT INTO public.research_companies (name, code, industry, seg, listed, round, last_funding, data, updated_at)
VALUES ('量智开物', '—', 'quantum', 'q-computing', false, '天使轮（产业合资）', '2026-03',
  '{"seg": "q-computing", "code": "—", "desc": "两仪万象与科大讯飞的合资公司，2026-03 成立，做 AI 智能体驱动的原子量子计算实验平台，2026-09 发布国内首个智能体原子量子计算实验平台「白泽」。不是整机厂商，卖的是让原子量子计算机跑得起来的软件与自动化层。", "name": "量智开物", "tech": [{"date": "2026-09", "kind": "产品", "title": "发布「白泽」智能体原子量子计算实验平台，已接入真实实验环境"}, {"date": "2026", "kind": "算法", "title": "「追风」AI 原子阵列重排：万量级原子阵列路径规划约 5 毫秒"}, {"date": "2026", "kind": "算法", "title": "「扁鹊」AI 量子纠错解码器：同时识别原子丢失与 Pauli 错误，无需额外硬件探测"}], "round": "天使轮（产业合资）", "listed": false, "funding": [{"inv": "两仪万象 200 万元、科大讯飞（北京）100 万元、安徽言知 100 万元、量智臻融 100 万元", "date": "2026-03", "round": "设立", "amount": "注册资本 500 万元"}], "industry": "quantum", "customers": "冷原子量子计算北京市重点实验室、清华大学原子量子计算团队（产学研协同）；科大讯飞为股东兼场景方。", "valuation": null, "descDetail": "中性原子整机的运行高度依赖人工：原子捕获有随机空位需重排、里德堡激发与门参数需逐项校准、原子丢失需实时判定。量智开物把这几件事交给智能体——实验需求理解、流程编排、参数调整、运行监测、异常处理。底层算法来自两仪万象团队：「追风」做万量级原子阵列的路径规划（约 5 毫秒），「扁鹊」做纠错解码，从测量数据的时空关联中同时识别原子丢失与常规 Pauli 错误，不需要额外增加探测原子丢失的硬件。", "executives": [{"bio": "量智开物工商登记全部职务集于一身（董事、经理、财务负责人），同时为两仪万象方代表，对外阐释「抓、控、算、纠」四环节框架与 AI 赋能量子计算的路径。", "name": "石琦", "title": "法定代表人、董事、经理、财务负责人", "tenure": "2026-03-18 至今"}], "latestTech": "白泽智能体平台：把原子量子实验的需求理解、流程编排、参数调整、监测与异常处理交给智能体，替代人工值守", "milestones": ["2026-09 发布国内首个智能体原子量子计算实验平台「白泽」", "2026-05-11 注册地址迁至海淀成府路 35 号院 AI 原点社区 J 座", "2026-04-23 完成股权变更，两仪万象、安徽言知、科大讯飞（北京）、量智臻融四家出资到位", "2026-03-18 量智开物（北京）科技有限公司成立，注册资本 500 万元，落户北京海淀"], "lastFunding": "2026-03", "productLine": ["白泽：智能体原子量子计算实验平台（需求理解 / 流程编排 / 参数调整 / 运行监测 / 异常处理）", "追风：万量级原子阵列 AI 重排算法，路径规划约 5ms", "扁鹊：AI 量子纠错解码器，原子丢失 + Pauli 错误联合识别"], "latestFunding": "2026-03 · 设立时注册资本 500 万元（两仪万象 40%、讯飞系 20%、安徽言知 20%、员工持股平台 20%）"}'::jsonb, now())
