INSERT INTO public.research_companies (name, code, industry, seg, listed, round, last_funding, data, updated_at)
VALUES ('相干科技', '—', 'quantum', 'q-computing', false, 'Pre-A+ 轮', '2026-06',
  '{"seg": "q-computing", "code": "—", "desc": "北京量子信息科学研究院孵化的首家超导量子计算整机企业，2023-10 成立，已打通「芯片—测控—整机—云平台」全链条，2026-11 首台整机「相干一号」获世界互联网大会「新光」产品。创始人为原北京量子院工程化攻关负责人金贻荣。", "name": "相干科技", "tech": [{"date": "2026-11", "kind": "产品", "title": "「相干一号」超导量子计算机整机获 2026 世界互联网大会「互联网之光」博览会「新光」产品"}, {"date": "2026-11", "kind": "产品", "title": "同台展出 286 比特、72 比特超导量子芯片、「相干云」量子计算云平台与测控电子学一体化方案"}, {"date": "2026", "kind": "指标", "title": "量子芯片平均单比特门保真度 >99.9%、平均双比特门保真度 >99.5%，10mK 环境稳定运行"}, {"date": "2026", "kind": "软件", "title": "Qxtrl 测控软件系统：AI 自动校准将 72 比特芯片校准时间由约两周压缩至 72 小时内"}, {"date": "2025", "kind": "基础设施", "title": "建成 136 比特超导量子计算云平台与 590 比特大规模量子云算力集群"}, {"date": "2024", "kind": "指标", "title": "实现 503 微秒长寿命超导量子比特芯片"}], "round": "Pre-A+ 轮", "listed": false, "funding": [{"inv": "北京市量子基金牵头领投", "date": "2026-06", "round": "Pre-A+", "amount": "超亿元"}, {"inv": "未披露", "date": "2026-02", "round": "Pre-A", "amount": "超亿元"}], "industry": "quantum", "customers": "金融、生物医药、材料新能源头部机构（场景落地推进中）；广州产投为战略投资方并协助落地海珠区子公司（2026-09）。", "valuation": null, "descDetail": "与本源量子并列为国内超导整机第一梯队，但打法和出身不同：相干科技是从新型研发机构整体孵化出来的工程化团队，先有 136 比特云平台和 590 比特集群的运营经验，再出来做公司，因此强项在测控电子学与系统集成，而不只是芯片指标。芯片侧已展示 286 比特与 72 比特两款；软件侧用 AI 做自动校准（Qxtrl），把 72 比特芯片约 3,000 次实验、1,000 个参数、两周的人工校准压到 72 小时内，这是超导路线规模化运维的真瓶颈。", "executives": [{"bio": "原北京量子信息科学研究院工程化攻关与生态建设一线技术负责人，主持研制 136 比特超导量子云平台、590 比特大规模量子云算力集群，实现 503 微秒长寿命超导量子比特芯片。2023 年从北京量子院孵化创办相干科技，为北京第一家超导量子计算企业。", "name": "金贻荣", "title": "创始人"}, {"bio": "负责对外业务与区域落地，主导广州海珠子公司设立及金融、生物医药、材料新能源场景推进。", "name": "黄浩", "title": "副总经理"}], "latestTech": "相干一号整机 + 286/72 比特芯片；单比特 >99.9%、双比特 >99.5%；Qxtrl 把 72 比特芯片校准从两周压到 72 小时", "milestones": ["2026-11 「相干一号」整机获世界互联网大会「新光」产品；新建 2,000+ 平方米研发中心，可容纳约 20 台稀释制冷机", "2026-09 在广州海珠区设立子公司（广州产投招引）", "2026-07 与粤科创投签署投资意向协议", "2026-06 完成超亿元 Pre-A+ 轮，北京市量子基金牵头领投", "2026-02 完成超亿元 Pre-A 轮，用于整机搭建与人员扩充", "2023-10-25 相干（北京）科技有限公司成立，孵化于北京量子信息科学研究院"], "lastFunding": "2026-06", "productLine": ["相干一号：第一代超导量子计算整机（2026-11 发布）", "超导量子芯片：286 比特、72 比特两款", "相干云：量子计算云平台", "测控电子学一体化解决方案（含 Qxtrl 自动校准软件）", "超导量子计算技术解决方案与算力服务"], "latestFunding": "2026-06 · Pre-A+ 超亿元（北京市量子基金领投）；累计完成多轮，团队由 20 余人增至近 70 人"}'::jsonb, now())
-- 若 name 无唯一约束，请改为先 SELECT 判断再 UPDATE/INSERT
ON CONFLICT (name) DO UPDATE SET data = EXCLUDED.data, round = EXCLUDED.round, last_funding = EXCLUDED.last_funding, updated_at = now();

INSERT INTO public.research_companies (name, code, industry, seg, listed, round, last_funding, data, updated_at)
VALUES ('伊辛智能', '—', 'quantum', 'q-computing', false, '累计超 1 亿元', '2026-09',
  '{"seg": "q-computing", "code": "—", "desc": "中科院半导体所孵化的光电伊辛机公司，用微波光子与光电参量振荡器做组合优化专用求解，常温机房可部署。与玻色量子同处「伊辛机/专用机」赛道，但物理载体不同（光电振荡 vs 光纤环 DOPO），是玻色在国内最直接的商业对手。", "name": "伊辛智能", "tech": [{"date": "2026-06", "kind": "产品", "title": "首款对外产品正式发布：4,000+ 自旋，单次稳定运行约 1.5 小时，整机功耗约 1,600W"}, {"date": "2026", "kind": "指标", "title": "最新系统实现 4,096 个全连接自旋，最长稳定振荡 5.5 小时"}, {"date": "2026", "kind": "基准", "title": "北京西二环交通数据实验：1,200 辆车调度构造为 485 自旋模型，物理求解 2.71ms，模拟退火基线 6.46s"}, {"date": "2022", "kind": "论文", "title": "Light: Science & Applications 发表大规模光电伊辛机成果：25,600 自旋、稳定运行超 12 小时"}, {"date": "2015", "kind": "技术起点", "title": "团队在中科院半导体所李明研究员团队开始光电振荡与光电参量振荡器研究"}], "round": "累计超 1 亿元", "listed": false, "funding": [{"inv": "顺禧天使基金领投，基石创投、国科创投、深智城跟投（值观资本任后续轮 FA）", "date": "2026-09", "round": "未披露轮次", "amount": "近亿元"}, {"inv": "达晨财智、广州产投加注", "date": "2025", "round": "—", "amount": "未披露"}, {"inv": "蓝驰创投、德联资本、麟阁创投、水木创投", "date": "2024", "round": "天使轮", "amount": "数千万元"}], "industry": "quantum", "customers": "金融、港口排泊、虚拟电厂调度场景已落地；广州产投为投资方，2025 年在广州海珠区设子公司及华南运营中心。", "valuation": null, "descDetail": "伊辛机不是门模型量子计算机，它把优化问题映射成自旋耦合系统，让物理系统自然演化到低能态，低能态即高质量解。伊辛智能走光电路线：短微波脉冲充当人工自旋，靠光电参量振荡器维持相位，FPGA 做控制。相比 D-Wave 的超导方案（需极低温、整机庞大、难进客户机房），光电方案的优势是常温、体积小、功耗低——首款对外产品 4,000+ 自旋、功耗约 1,600W、体积可控制在冰箱甚至家用电脑量级。", "executives": [{"bio": "90 后博士，技术源自中科院半导体所李明研究员团队（2015 年起做光电振荡与光电参量振荡器）。公司 2024-03 注册、2025-01 正式运营，2024-09 首笔融资到账。对外主张伊辛机在异构计算中的定位是「优化处理器」，与 GPU 是协作而非替代关系。", "name": "肖晔", "title": "联合创始人、CEO"}, {"bio": "负责对外业务与场景落地，主导金融、港口排泊、虚拟电厂调度等标杆案例。", "name": "韩硕", "title": "高级副总裁"}], "latestTech": "首款对外产品 4,000+ 自旋、功耗约 1,600W、常温机房部署；学术系统已达 4,096 全连接自旋、稳定 5.5 小时", "milestones": ["2026-09 完成近亿元新一轮融资，顺禧天使基金领投", "2026-06 首款对外产品正式发布，从「能用」推进到「易用」", "2025-01 正式启动运营（公司 2024-03 注册，首笔融资 2024-09 到账）", "2024-07 公司成立运营，天使轮即获蓝驰创投、德联资本、麟阁创投、水木创投投资"], "lastFunding": "2026-09", "productLine": ["光电伊辛机整机：4,000+ 自旋，常温机房部署，功耗约 1,600W，体积冰箱量级", "端到端组合优化项目交付（问题建模 + 现场编程 + 结果解码）", "云端 API 调用（比赛与 POC 已验证，几秒内返回）"], "latestFunding": "2026-09 · 新一轮近亿元（顺禧天使基金领投）；成立两年累计融资超 1 亿元"}'::jsonb, now())
-- 若 name 无唯一约束，请改为先 SELECT 判断再 UPDATE/INSERT
ON CONFLICT (name) DO UPDATE SET data = EXCLUDED.data, round = EXCLUDED.round, last_funding = EXCLUDED.last_funding, updated_at = now();